// Parse the OCR data
const ocrData = $input.first().json;
const markdown = ocrData.pages[0].markdown;

// Function to parse the markdown table into structured data
function parseRosterTable(markdown) {
  const lines = markdown.split('\n');

  // Find the header rows
  let userNameIndex = -1;
  let dateIndices = [];
  let headerRowIndex = -1;

  // Search through all rows to find the one with UserName and dates
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // Skip empty lines and separator lines
    if (!line.trim() || line.includes('---')) {
      continue;
    }

    // Check if this line contains UserName
    if (line.includes('UserName') || line.includes('User Name')) {
      headerRowIndex = i;
      const headerRow = line.split('|').map(cell => cell.trim());

      // Find UserName column index
      for (let j = 0; j < headerRow.length; j++) {
        if (headerRow[j].includes('UserName') || headerRow[j].includes('User Name')) {
          userNameIndex = j;
          break;
        }
      }

      // Now look for the date row - it could be above or below the UserName row
      // Check the row above (dates might be before UserName)
      if (i > 0) {
        const prevLine = lines[i - 1];
        if (prevLine && !prevLine.includes('---')) {
          const prevRow = prevLine.split('|').map(cell => cell.trim());
          for (let j = 0; j < prevRow.length; j++) {
            if (prevRow[j].match(/\d{1,2}-[A-Za-z]{3,}/)) {
              dateIndices.push({
                index: j,
                date: prevRow[j].trim()
              });
            }
          }
        }
      }

      // If no dates found above, check current row
      if (dateIndices.length === 0) {
        for (let j = 0; j < headerRow.length; j++) {
          if (headerRow[j].match(/\d{1,2}-[A-Za-z]{3,}/)) {
            dateIndices.push({
              index: j,
              date: headerRow[j].trim()
            });
          }
        }
      }

      // If still no dates found, check the row below
      if (dateIndices.length === 0 && i < lines.length - 1) {
        const nextLine = lines[i + 1];
        if (nextLine && !nextLine.includes('---')) {
          const nextRow = nextLine.split('|').map(cell => cell.trim());
          for (let j = 0; j < nextRow.length; j++) {
            if (nextRow[j].match(/\d{1,2}-[A-Za-z]{3,}/)) {
              dateIndices.push({
                index: j,
                date: nextRow[j].trim()
              });
            }
          }
        }
      }

      break;
    }
  }

  if (userNameIndex === -1 || dateIndices.length === 0) {
    throw new Error('Could not find header row with UserName and dates');
  }

  // Extract roster data
  const rosterData = [];
  const year = new Date().getFullYear();

  // Process rows starting from after the header row
  for (let i = headerRowIndex + 1; i < lines.length; i++) {
    const line = lines[i];

    // Skip empty lines, separator lines, and summary rows
    if (!line.trim() || line.includes('---') || line.includes('Total') || line.includes('Sheet')) {
      continue;
    }

    const row = line.split('|').map(cell => cell.trim());

    // Check if this is a valid engineer row
    if (row.length > userNameIndex && row[userNameIndex] && 
        !row[userNameIndex].match(/^(Total|A|B|G|L|CO|WO|WH|Absent|Aug|Sheet|D\d+|Fri|Sat|Sun|Mon|Tue|Wed|Thu)$/) && 
        row[userNameIndex] !== '' && 
        row[userNameIndex].length > 2) {  // Engineer names should be longer than 2 characters

      const engineerName = row[userNameIndex];

      // For each date column, extract the shift type
      dateIndices.forEach(dateInfo => {
        if (row.length > dateInfo.index && row[dateInfo.index]) {
          const shiftType = row[dateInfo.index];

          // Convert date string (e.g., "08-Aug") to ISO format (e.g., "2025-08-08")
          const dateParts = dateInfo.date.split('-');
          const day = dateParts[0].padStart(2, '0');
          const month = new Date(`${dateParts[1]} 1, 2000`).getMonth() + 1;
          const formattedDate = `${year}-${month.toString().padStart(2, '0')}-${day}`;

          // Add entry to roster data - filter out invalid shift types
          if (shiftType && 
              shiftType !== '' && 
              !shiftType.match(/^(\d+|D\d+|Fri|Sat|Sun|Mon|Tue|Wed|Thu|Total|Sheet|---)$/)) {
            rosterData.push({
              engineer_name: engineerName,
              date: formattedDate,
              shift_type: shiftType
            });
          }
        }
      });
    }
  }

  return rosterData;
}

