                         '08-Aug', '09-Aug', '10-Aug', '11-Aug', '12-Aug', '13-Aug', '14-Aug',
                         'Sheet1', 'Sheet2', '---'];

// Create a clean copy of the data with invalid entries removed
const cleanedData = rawData.data.filter(entry => {
  // Skip entries with invalid engineer names
  if (invalidNames.includes(entry.engineer_name.trim())) {
    return false;
  }

  // Skip entries with invalid shift types
  if (invalidShiftTypes.includes(entry.shift_type.trim())) {
    return false;
  }

  return true;
});

// Update counts and return the cleaned data
return {
  success: rawData.success,
  data: cleanedData,
  count: cleanedData.length,
  originalCount: rawData.data.length,
  filtered: rawData.data.length - cleanedData.length,
  message: rawData.message
