// Get the cleaned roster data and engineer IDs
const rosterData = $node["Clean Roster Data"].json.data;

// Get all input items from the previous node
const allInputs = $input.all();

// Extract the engineer data - it could be in different formats
let engineerIds = [];

// Method 1: If all inputs contain the engineer data
if (allInputs.length > 0) {
  // Check if first input contains an array
  const firstInput = allInputs[0].json;
  if (Array.isArray(firstInput)) {
    engineerIds = firstInput;
  } else {
    // Each input is a single engineer - collect them all
