  }
}

// Ensure we have an array
if (!Array.isArray(engineerIds) || engineerIds.length === 0) {
  throw new Error(`Expected array but got: ${typeof engineerIds}. AllInputs length: ${allInputs.length}. First input: ${JSON.stringify(allInputs[0]?.json)}`);
}

// Create a mapping from engineer names to IDs
const engineerNameToId = {};
for (const engineer of engineerIds) {
  if (engineer && engineer.name && engineer.id) {
    engineerNameToId[engineer.name] = engineer.id;
  }
}

// Generate conflict check queries for each roster entry - include last_updated
const queries = [];

for (const entry of rosterData) {
  const engineerId = engineerNameToId[entry.engineer_name];

  if (engineerId) {
    queries.push({
      engineer_id: engineerId,
      engineer_name: entry.engineer_name,
      date: entry.date,
      new_shift_type: entry.shift_type,
      query: `SELECT engineer_id, date, shift_type, last_updated FROM roster_automation_flow_roster WHERE engineer_id = ${engineerId} AND date = '${entry.date}'`
    });
  }
}

return queries;

// Get all the conflict check results and original query data
const allItems = $input.all();
const rosterData = $("Clean Roster Data").first().json.data;
const queryInputs = $("Generate Conflict Check Queries").all();

// Get engineer IDs - handle the case where MySQL returns individual items
const engineerIdsInputs = $("Get Engineer IDs").all();
let engineerIds = [];
if (engineerIdsInputs.length > 0) {
  const firstInput = engineerIdsInputs[0].json;
  if (Array.isArray(firstInput)) {
    engineerIds = firstInput;
  } else {
    // Each input is a single engineer - collect them all
    engineerIds = engineerIdsInputs.map(item => item.json);
  }
}

// Create engineer name to ID mapping
const engineerNameToId = {};
for (const engineer of engineerIds) {
  engineerNameToId[engineer.name] = engineer.id;
}

// Create a map of query results by engineer_id and date for easy lookup
const queryResultsMap = new Map();
for (const item of allItems) {
  if (item && item.json && typeof item.json === 'object') {
    // Check if the json property has the expected database fields
    if (item.json.engineer_id !== undefined && 
        item.json.date !== undefined && 
        item.json.shift_type !== undefined) {
      const key = `${item.json.engineer_id}_${item.json.date}`;
      queryResultsMap.set(key, item.json);
    }
  }
}

// Analyze results
const conflicts = [];
const existingEntries = [];
const newEntries = [];

// Process each query input to determine the status
for (const queryInputItem of queryInputs) {
  const queryInput = queryInputItem.json;

  // Create lookup key for this query
  const lookupKey = `${queryInput.engineer_id}_${queryInput.date}`;
  const queryResult = queryResultsMap.get(lookupKey);

  // Get the original entry data from the query input
  const originalEntry = {
    engineer_id: queryInput.engineer_id,
    engineer_name: queryInput.engineer_name,
    date: queryInput.date,
    shift_type: queryInput.new_shift_type
  };

  // Check if we found an existing entry in the database
  if (!queryResult) {
    // No existing entry found - this is a new entry
    newEntries.push({
      engineer_id: originalEntry.engineer_id,
      engineer_name: originalEntry.engineer_name,
      date: originalEntry.date,
      shift_type: originalEntry.shift_type
    });
  } else {
    // Existing entry found - compare shift types
    if (queryResult.shift_type === originalEntry.shift_type) {
      // Same shift type - no conflict, entry already exists
      existingEntries.push({
        engineer_id: queryResult.engineer_id,
        engineer_name: originalEntry.engineer_name,
        date: originalEntry.date,
        shift_type: originalEntry.shift_type,
        last_updated: queryResult.last_updated
      });
    } else {
      // Different shift type - this is a conflict
      conflicts.push({
        engineer_id: queryResult.engineer_id,
        engineer_name: originalEntry.engineer_name,
        date: originalEntry.date,
        old_shift_type: queryResult.shift_type,
        new_shift_type: originalEntry.shift_type,
        last_updated: queryResult.last_updated
      });
    }
  }
}

