const storedData = conflictRecord.conflict_data;
const sessionId = conflictRecord.session_id;

// Determine user's choice
const isApproved = userMessage === 'yes' || userMessage === '✅' || userMessage === 'approve';
const isRejected = userMessage === 'no' || userMessage === '❌' || userMessage === 'reject';

if (isApproved) {
