// Handle conflicts - update existing entries
for (const conflict of conflicts) {
  const updateSql = `UPDATE roster_automation_flow_roster SET shift_type = '${conflict.new_shift_type}', last_updated = CURRENT_TIMESTAMP WHERE engineer_id = ${conflict.engineer_id} AND date = '${conflict.date}'`;
  sqlOperations.push(updateSql);

  // Also log the conflict resolution
  const logSql = `INSERT INTO roster_automation_flow_conflicts (engineer_id, date, old_shift_type, new_shift_type, resolved_by, resolved_at) VALUES (${conflict.engineer_id}, '${conflict.date}', '${conflict.old_shift_type}', '${conflict.new_shift_type}', 'telegram_user', CURRENT_TIMESTAMP)`;
  sqlOperations.push(logSql);
}

// DO NOT process new entries here - they were already processed earlier!

// Generate detailed amendment message
let message = '✅ **Roster Updated Successfully!**\n\n';

if (conflicts.length > 0) {
  message += '🔄 **Conflicts Resolved:**\n';
  conflicts.forEach((conflict, index) => {
    message += `${index + 1}. **${conflict.engineer_name}** - ${conflict.date}\n`;
    message += `   • Changed: ${conflict.old_shift_type} ➜ ${conflict.new_shift_type}\n`;
  });
  message += '\n';
}

message += '📊 **Summary:**\n';
message += `• Conflicts resolved: ${conflicts.length}\n`;
message += `• Conflict operations: ${sqlOperations.length}\n`;
message += `• Status: All updates completed successfully ✅\n\n`;
message += `🕒 Updated at: ${new Date().toLocaleString()}`;

return {
  sqlOperations: sqlOperations,
  conflictsResolved: conflicts.length,
  newEntriesAlreadyAdded: newEntriesAlreadyProcessed,
  chatId: inputData.chatId,
  sessionId: inputData.sessionId,
  conflicts: conflicts,
  message: message
};

