  conflicts.forEach((conflict, index) => {
    message += `${index + 1}. *${conflict.engineer_name}* - ${conflict.date}\n`;
    message += `   • Changed: ${conflict.old_shift_type} ➜ ${conflict.new_shift_type}\n`;
  });
  message += '\n';
}

message += '📊 *Summary:*\n';
message += `• Conflicts resolved: ${conflicts.length}\n`;
message += `• Conflict operations: ${sqlOperations.length}\n`;
message += `• Status: All updates completed successfully ✅\n\n`;
message += `🕒 Updated at: ${new Date().toLocaleString()}`;

return {
  sqlOperations: sqlOperations,
  conflictsResolved: conflicts.length,
  newEntriesAlreadyAdded: newEntriesAlreadyProcessed,
  chatId: inputData.chatId,
  sessionId: inputData.sessionId,
  conflicts: conflicts,
  message: message
};

